protected override void OnModelCreating(ModelBuilder modelBuilder)
{
    modelBuilder.Entity<Product>(entity =>
    {
        entity.ToContainer("Products");

        // EF Core 9 renamed the default discriminator from "Discriminator" to "$type".
        // Preserve the old name so existing 500K documents remain queryable.
        entity.HasDiscriminator<string>("Discriminator");

        // EF Core 9 removed the entity-type prefix from id values ("Product|123" → "123").
        // Preserve the old compound format so existing documents are still found.
        entity.HasRootDiscriminatorInJsonId(true);
    });
    // HasIndex removed — Cosmos DB provider now throws at startup.
    // Manage indexing via the container's indexing policy (Azure Portal / Bicep / Terraform).
}

